pub const Similarity = struct {
    common: i64,
    union_count: i64,
    pub fn less(self: Similarity, other: Similarity) bool {
        return self.common * other.union_count < other.common * self.union_count;
    }
    pub fn text(self: Similarity) []const u8 {
        var a = self.common;
        var b = self.union_count;
        while (b != 0) {
            const next = @mod(a, b);
            a = b;
            b = next;
        }
        return m.fmt("{d}/{d}", .{ @divTrunc(self.common, a), @divTrunc(self.union_count, a) });
    }
pub fn tanimoto(first: Fingerprint, second: Fingerprint) Similarity {
    var common: i64 = 0;
    var union_count: i64 = 0;
    for (first.bits, second.bits) |a, b| {
        common += @popCount(a & b);
        union_count += @popCount(a | b);
    }
    return .{ .common = common, .union_count = union_count };
}
const Similarities = struct {
    count: usize,
    values: []search.Similarity,
    fn init(molecules: []const Prepared) Similarities {
        const values = m.alloc(search.Similarity, molecules.len * molecules.len);
        for (molecules, 0..) |first, a| for (molecules[a..], a..) |second, b| {
            const value = search.tanimoto(first.fingerprint, second.fingerprint);
            values[a * molecules.len + b] = value;
            values[b * molecules.len + a] = value;
        };
        return .{ .count = molecules.len, .values = values };
    }
    fn get(self: Similarities, a: usize, b: usize) search.Similarity {
        return self.values[a * self.count + b];
    }
